        {
            @Point.started -= instance.OnPoint;
            @Point.performed -= instance.OnPoint;
            @Point.canceled -= instance.OnPoint;
            @Click.started -= instance.OnClick;
            @Click.performed -= instance.OnClick;
            @Click.canceled -= instance.OnClick;
        }

        /// <summary>
        /// Unregisters <param cref="instance" /> and unregisters all input action callbacks via <see cref="SharedUIActions.UnregisterCallbacks(ISharedUIActions)" />.
        /// </summary>
        /// <seealso cref="SharedUIActions.UnregisterCallbacks(ISharedUIActions)" />
        public void RemoveCallbacks(ISharedUIActions instance)
        {
            if (m_Wrapper.m_SharedUIActionsCallbackInterfaces.Remove(instance))
                UnregisterCallbacks(instance);
        }

        /// <summary>
        /// Replaces all existing callback instances and previously registered input action callbacks associated with them with callbacks provided via <param cref="instance" />.
        /// </summary>
        /// <remarks>
        /// If <paramref name="instance" /> is <c>null</c>, calling this method will only unregister all existing callbacks but not register any new callbacks.
        /// </remarks>
        /// <seealso cref="SharedUIActions.AddCallbacks(ISharedUIActions)" />
        /// <seealso cref="SharedUIActions.RemoveCallbacks(ISharedUIActions)" />
        /// <seealso cref="SharedUIActions.UnregisterCallbacks(ISharedUIActions)" />
        public void SetCallbacks(ISharedUIActions instance)
        {
            foreach (var item in m_Wrapper.m_SharedUIActionsCallbackInterfaces)
                UnregisterCallbacks(item);
            m_Wrapper.m_SharedUIActionsCallbackInterfaces.Clear();
            AddCallbacks(instance);
        }
    }
